-- RLS asas. Polisi produksi perlu disesuaikan dengan Supabase Auth JWT role/user mapping.
alter table ngaji_students enable row level security; alter table ngaji_teachers enable row level security; alter table ngaji_attendance enable row level security; alter table ngaji_assessments enable row level security; alter table ngaji_assessment_scores enable row level security;
